1	package cmd
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"net/http"
9		"os"
10		"path/filepath"
11		"strings"
12		"time"
13	
14		tea "github.com/charmbracelet/bubbletea"
15		"github.com/spf13/cobra"
16		"golang.org/x/term"
17	
18		"github.com/immuta/operations/apps/birdseye/internal/archive"
19		"github.com/immuta/operations/apps/birdseye/internal/diff"
20		"github.com/immuta/operations/apps/birdseye/internal/registry"
21		"github.com/immuta/operations/apps/birdseye/internal/tui"
22		"github.com/immuta/operations/services/crow/pkg/api"
23		"github.com/immuta/operations/services/crow/pkg/client"
24	)
25	
26	// diffOpts holds the resolved options for `birdseye diff`.
27	type diffOpts struct {
28		Semantic bool
29		Plain    bool
30		CacheDir string
31	}
32	
33	const maxArchiveBytes = 50 << 20 // 50 MiB safety cap on uncompressed size
34	
35	func newDiffCmd(g *GlobalFlags) *cobra.Command {
36		o := &diffOpts{}
37		c := &cobra.Command{
38			Use:   "diff [module] [versionA] [versionB]",
39			Short: "Diff two versions of a Crow module",
40			Long: "Diff two versions of a module hosted in Crow.\n\n" +
41				"If module/versions are omitted, the interactive TUI launches\n" +
42				"(see picker task). With --plain, prints unified diff to stdout.",
43			Args:          cobra.MaximumNArgs(3),
44			SilenceUsage:  true,
45			SilenceErrors: true,
46			RunE: func(cmd *cobra.Command, args []string) error {
47				return runDiff(cmd.Context(), cmd, args, g, o)
48			},
49		}
50		c.Flags().BoolVar(&o.Semantic, "semantic", false, "include HCL-aware semantic diff alongside textual")
51		c.Flags().BoolVar(&o.Plain, "plain", false, "force plain (non-TUI) output")
52		c.Flags().BoolVar(&o.Plain, "no-tui", false, "alias for --plain")
53		c.Flags().StringVar(&o.CacheDir, "cache-dir", defaultCacheDir(), "module tarball cache directory")
54		return c
55	}
56	
57	func defaultCacheDir() string {
58		if home, err := os.UserCacheDir(); err == nil {
59			return filepath.Join(home, "birdseye")
60		}
61		return ".birdseye-cache"
62	}
63	
64	func newHTTPClient(d time.Duration) *http.Client {
65		return &http.Client{Timeout: d}
66	}
67	
68	func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
69		parts := strings.Split(s, "/")
70		if len(parts) != 3 {
71			return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
72		}
73		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
74		if err := id.Validate(); err != nil {
75			return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
76		}
77		return id, nil
78	}
79	
80	func runDiff(ctx context.Context, cmd *cobra.Command, args []string, g *GlobalFlags, o *diffOpts) error {
81		if len(args) == 0 {
82			return runInteractive(ctx, cmd, g, o)
83		}
84		if len(args) != 3 {
85			return fmt.Errorf("%w: diff requires <module> <versionA> <versionB>", ErrUsage)
86		}
87		id, err := parseModuleAddress(args[0])
88		if err != nil {
89			return err
90		}
91		if err := api.ValidateVersion(args[1]); err != nil {
92			return fmt.Errorf("%w: %v", ErrUsage, err)
93		}
94		if err := api.ValidateVersion(args[2]); err != nil {
95			return fmt.Errorf("%w: %v", ErrUsage, err)
96		}
97		modA := api.Module{ModuleIdentifier: id, Version: args[1]}
98		modB := api.Module{ModuleIdentifier: id, Version: args[2]}
99	
100		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
101		cache, err := registry.NewDiskCache(o.CacheDir)
102		if err != nil {
103			return fmt.Errorf("cache init: %w", err)
104		}
105		reg := registry.New(cli, cache)
106	
107		aBytes, bBytes, err := reg.FetchPair(ctx, modA, modB)
108		if err != nil {
109			return err
110		}
111	
112		modAExtracted, err := archive.Extract(aBytes, maxArchiveBytes)
113		if err != nil {
114			return fmt.Errorf("%w: %v", ErrArchive, err)
115		}
116		modBExtracted, err := archive.Extract(bBytes, maxArchiveBytes)
117		if err != nil {
118			return fmt.Errorf("%w: %v", ErrArchive, err)
119		}
120	
121		result := diff.Result{Files: diff.Textual(modAExtracted, modBExtracted)}
122		if o.Semantic {
123			sem, err := diff.Semantic(modAExtracted, modBExtracted)
124			if err != nil {
125				return fmt.Errorf("%w: %v", ErrSemantic, err)
126			}
127			result.Semantic = sem
128		}
129	
130		if g.JSON {
131			return renderJSON(cmd.OutOrStdout(), result)
132		}
133		if !o.Plain && isTTY(cmd.OutOrStdout()) {
134			return tui.RunBrowser(ctx, result)
135		}
136		return renderPlain(cmd.OutOrStdout(), result)
137	}
138	
139	// isTTY reports whether w is a *os.File backed by a terminal.
140	func isTTY(w io.Writer) bool {
141		f, ok := w.(*os.File)
142		if !ok {
143			return false
144		}
145		return term.IsTerminal(int(f.Fd()))
146	}
147	
148	func runInteractive(ctx context.Context, cmd *cobra.Command, g *GlobalFlags, o *diffOpts) error {
149		if !isTTY(cmd.OutOrStdout()) {
150			return fmt.Errorf("%w: interactive mode requires a TTY", ErrUsage)
151		}
152		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
153		cache, err := registry.NewDiskCache(o.CacheDir)
154		if err != nil {
155			return fmt.Errorf("cache init: %w", err)
156		}
157		reg := registry.New(cli, cache)
158	
159		// Stage 1: picker → fetched bytes
160		p := tui.NewPicker(&tui.Deps{Client: cli, Reg: reg})
161		prog := tea.NewProgram(p, tea.WithAltScreen(), tea.WithContext(ctx))
162		if _, err := prog.Run(); err != nil {
163			return err
164		}
165		aBytes, bBytes := p.Bytes()
166		if aBytes == nil || bBytes == nil {
167			// User quit before completing picker; not an error.
168			return nil
169		}
170	
171		// Stage 2: extract + diff + browser
172		modA, err := archive.Extract(aBytes, maxArchiveBytes)
173		if err != nil {
174			return fmt.Errorf("%w: %v", ErrArchive, err)
175		}
176		modB, err := archive.Extract(bBytes, maxArchiveBytes)
177		if err != nil {
178			return fmt.Errorf("%w: %v", ErrArchive, err)
179		}
180		result := diff.Result{Files: diff.Textual(modA, modB)}
181		return tui.RunBrowser(ctx, result)
182	}
183	
184	// renderPlain writes the diff result to w in unified-diff format.
185	// "no differences" is emitted when there are zero files in the result.
186	func renderPlain(w io.Writer, r diff.Result) error {
187		if len(r.Files) == 0 && len(r.Semantic) == 0 {
188			_, err := fmt.Fprintln(w, "no differences")
189			return err
190		}
191		for i, fd := range r.Files {
192			if i > 0 {
193				_, _ = fmt.Fprintln(w)
194			}
195			_, _ = fmt.Fprintf(w, "=== %s (%s) +%d -%d\n", fd.Path, fd.Status, fd.Adds, fd.Dels)
196			_, _ = fmt.Fprint(w, fd.Unified)
197		}
198		if len(r.Semantic) > 0 {
199			_, _ = fmt.Fprintln(w)
200			_, _ = fmt.Fprintln(w, "=== semantic changes ===")
201			for _, c := range r.Semantic {
202				_, _ = fmt.Fprintf(w, "%s %s %s\n", c.Status, c.Kind, c.Name)
203			}
204		}
205		return nil
206	}
207	
208	func renderJSON(w io.Writer, r diff.Result) error {
209		type fileOut struct {
210			Path    string `json:"path"`
211			Status  string `json:"status"`
212			Adds    int    `json:"adds"`
213			Dels    int    `json:"dels"`
214			Unified string `json:"unified"`
215		}
216		type semOut struct {
217			Kind   string `json:"kind"`
218			Name   string `json:"name"`
219			Status string `json:"status"`
220			Detail string `json:"detail,omitempty"`
221		}
222		type payload struct {
223			Files    []fileOut `json:"files"`
224			Semantic []semOut  `json:"semantic,omitempty"`
225		}
226		out := payload{Files: make([]fileOut, 0, len(r.Files))}
227		for _, fd := range r.Files {
228			out.Files = append(out.Files, fileOut{Path: fd.Path, Status: fd.Status.String(), Adds: fd.Adds, Dels: fd.Dels, Unified: fd.Unified})
229		}
230		for _, c := range r.Semantic {
231			out.Semantic = append(out.Semantic, semOut{Kind: c.Kind, Name: c.Name, Status: c.Status.String(), Detail: c.Detail})
232		}
233		return json.NewEncoder(w).Encode(out)
234	}
