1	package registry
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7	
8		"github.com/immuta/operations/services/crow/pkg/api"
9		"github.com/immuta/operations/services/crow/pkg/client"
10		"golang.org/x/sync/errgroup"
11	)
12	
13	// Registry composes a typed Crow client with a Cache. Fetch is cache-first;
14	// FetchPair fans Fetch out concurrently with shared cancellation.
15	type Registry struct {
16		client *client.Client
17		cache  Cache
18	}
19	
20	// New constructs a Registry. Both arguments must be non-nil.
21	func New(c *client.Client, cache Cache) *Registry {
22		return &Registry{client: c, cache: cache}
23	}
24	
25	// Fetch returns the gzipped tarball bytes for the given module version,
26	// consulting the cache first. Network errors and 404s from the
27	// underlying client surface unchanged (callers can errors.Is against
28	// client.ErrNotFound).
29	func (r *Registry) Fetch(ctx context.Context, m api.Module) ([]byte, error) {
30		if body, hit, err := r.cache.Get(m); err != nil {
31			return nil, fmt.Errorf("cache get: %w", err)
32		} else if hit {
33			return body, nil
34		}
35		rc, err := r.client.Download(ctx, m)
36		if err != nil {
37			return nil, err
38		}
39		defer rc.Close()
40		body, err := io.ReadAll(rc)
41		if err != nil {
42			return nil, fmt.Errorf("read tarball: %w", err)
43		}
44		if err := r.cache.Put(m, body); err != nil {
45			// Cache write failure is not fatal — we still have the body to return.
46			_ = err
47		}
48		return body, nil
49	}
50	
51	// FetchPair fetches a and b concurrently. The first error cancels its
52	// sibling via errgroup.WithContext.
53	func (r *Registry) FetchPair(ctx context.Context, a, b api.Module) ([]byte, []byte, error) {
54		g, gctx := errgroup.WithContext(ctx)
55		var aBytes, bBytes []byte
56		g.Go(func() error {
57			body, err := r.Fetch(gctx, a)
58			if err != nil {
59				return err
60			}
61			aBytes = body
62			return nil
63		})
64		g.Go(func() error {
65			body, err := r.Fetch(gctx, b)
66			if err != nil {
67				return err
68			}
69			bBytes = body
70			return nil
71		})
72		if err := g.Wait(); err != nil {
73			return nil, nil, err
74		}
75		return aBytes, bBytes, nil
76	}
