1	// Package registry talks to a Crow server through its typed client and
2	// caches module tarballs on disk so repeated diffs against the same
3	// versions stay fast.
4	package registry
5	
6	import (
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sync"
12	
13		"github.com/immuta/operations/services/crow/pkg/api"
14	)
15	
16	// Cache is the storage seam used by Registry. Production uses DiskCache;
17	// tests inject MemCache.
18	type Cache interface {
19		Get(api.Module) ([]byte, bool, error)
20		Put(api.Module, []byte) error
21	}
22	
23	// MemCache is a thread-safe in-memory Cache implementation.
24	type MemCache struct {
25		mu    sync.RWMutex
26		items map[string][]byte
27	}
28	
29	// NewMemCache returns an empty MemCache.
30	func NewMemCache() *MemCache {
31		return &MemCache{items: make(map[string][]byte)}
32	}
33	
34	func memKey(m api.Module) string {
35		return m.Namespace + "/" + m.Name + "/" + m.Provider + "/" + m.Version
36	}
37	
38	func (c *MemCache) Get(m api.Module) ([]byte, bool, error) {
39		c.mu.RLock()
40		defer c.mu.RUnlock()
41		b, ok := c.items[memKey(m)]
42		if !ok {
43			return nil, false, nil
44		}
45		return b, true, nil
46	}
47	
48	func (c *MemCache) Put(m api.Module, body []byte) error {
49		c.mu.Lock()
50		defer c.mu.Unlock()
51		c.items[memKey(m)] = body
52		return nil
53	}
54	
55	// DiskCache stores tarballs under
56	//
57	//	<root>/<namespace>/<name>/<provider>/<version>.tar.gz
58	//
59	// Writes are atomic via a temp file + rename.
60	type DiskCache struct {
61		root string
62	}
63	
64	// NewDiskCache creates the root directory if it does not exist.
65	func NewDiskCache(root string) (*DiskCache, error) {
66		if err := os.MkdirAll(root, 0o755); err != nil {
67			return nil, fmt.Errorf("mkdir cache root: %w", err)
68		}
69		return &DiskCache{root: root}, nil
70	}
71	
72	func (c *DiskCache) path(m api.Module) string {
73		return filepath.Join(c.root, m.Namespace, m.Name, m.Provider, m.Version+".tar.gz")
74	}
75	
76	func (c *DiskCache) Get(m api.Module) ([]byte, bool, error) {
77		b, err := os.ReadFile(c.path(m))
78		if errors.Is(err, os.ErrNotExist) {
79			return nil, false, nil
80		}
81		if err != nil {
82			return nil, false, fmt.Errorf("read cache: %w", err)
83		}
84		return b, true, nil
85	}
86	
87	func (c *DiskCache) Put(m api.Module, body []byte) error {
88		final := c.path(m)
89		if err := os.MkdirAll(filepath.Dir(final), 0o755); err != nil {
90			return fmt.Errorf("mkdir cache dir: %w", err)
91		}
92		tmp, err := os.CreateTemp(filepath.Dir(final), ".birdseye-*.tmp")
93		if err != nil {
94			return fmt.Errorf("create temp: %w", err)
95		}
96		tmpName := tmp.Name()
97		if _, err := tmp.Write(body); err != nil {
98			_ = tmp.Close()
99			_ = os.Remove(tmpName)
100			return fmt.Errorf("write temp: %w", err)
101		}
102		if err := tmp.Close(); err != nil {
103			_ = os.Remove(tmpName)
104			return fmt.Errorf("close temp: %w", err)
105		}
106		if err := os.Rename(tmpName, final); err != nil {
107			_ = os.Remove(tmpName)
108			return fmt.Errorf("rename: %w", err)
109		}
110		return nil
111	}
