1	package tui
2	
3	import (
4		"context"
5		"fmt"
6		"strings"
7	
8		"github.com/charmbracelet/bubbles/list"
9		"github.com/charmbracelet/bubbles/spinner"
10		"github.com/charmbracelet/bubbles/textinput"
11		tea "github.com/charmbracelet/bubbletea"
12	
13		"github.com/immuta/operations/apps/birdseye/internal/registry"
14		"github.com/immuta/operations/services/crow/pkg/api"
15		"github.com/immuta/operations/services/crow/pkg/client"
16	)
17	
18	// PickerState is the explicit state machine the picker walks.
19	type PickerState int
20	
21	const (
22		StateAskModule PickerState = iota
23		StateAskVersionA
24		StateAskVersionB
25		StateLoading
26		StateBrowser
27		StateError
28	)
29	
30	// Deps groups the picker's external dependencies. nil is acceptable for
31	// unit tests of the picker's input/state machinery (those tests never
32	// reach StateLoading).
33	type Deps struct {
34		Client *client.Client
35		Reg    *registry.Registry
36	}
37	
38	type versionsLoadedMsg struct {
39		versions []string
40		err      error
41	}
42	
43	type pairLoadedMsg struct {
44		a, b []byte
45		err  error
46	}
47	
48	// versionItem implements bubbles/list.Item for a single version string.
49	type versionItem string
50	
51	func (v versionItem) FilterValue() string { return string(v) }
52	func (v versionItem) Title() string       { return string(v) }
53	func (v versionItem) Description() string { return "" }
54	
55	// Picker is a single bubbletea Model whose internal state enum drives
56	// which sub-widget is rendered.
57	type Picker struct {
58		deps       *Deps
59		state      PickerState
60		input      textinput.Model
61		moduleID   api.ModuleIdentifier
62		versionsA  list.Model
63		versionsB  list.Model
64		chosenA    string
65		chosenB    string
66		spinner    spinner.Model
67		browser    *Browser
68		width      int
69		height     int
70		errMessage string
71		pairA      []byte
72		pairB      []byte
73	}
74	
75	// NewPicker constructs a picker. deps may be nil for input-only tests
76	// (no network dispatch occurs in that case).
77	func NewPicker(deps *Deps) *Picker {
78		ti := textinput.New()
79		ti.Placeholder = "namespace/name/provider"
80		ti.Focus()
81		sp := spinner.New()
82		sp.Spinner = spinner.Dot
83		return &Picker{
84			deps:    deps,
85			state:   StateAskModule,
86			input:   ti,
87			spinner: sp,
88		}
89	}
90	
91	func (p *Picker) State() PickerState { return p.state }
92	func (p *Picker) HasError() bool     { return p.errMessage != "" }
93	
94	// Bytes returns the fetched tarballs once StateBrowser is reached, so
95	// the cmd integration can extract + diff and build the browser.
96	func (p *Picker) Bytes() ([]byte, []byte) { return p.pairA, p.pairB }
97	
98	// SetBrowser hands a pre-built Browser to the picker. Used by the cmd
99	// integration after FetchPair completes (the cmd does the extract+diff
100	// step and supplies the resulting browser here).
101	func (p *Picker) SetBrowser(b *Browser) {
102		p.browser = b
103		if p.width > 0 {
104			b.SetSize(p.width, p.height)
105		}
106		p.state = StateBrowser
107	}
108	
109	func (p *Picker) Init() tea.Cmd { return textinput.Blink }
110	
111	func (p *Picker) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
112		switch msg := msg.(type) {
113		case tea.WindowSizeMsg:
114			p.width, p.height = msg.Width, msg.Height
115			if p.browser != nil {
116				p.browser.SetSize(msg.Width, msg.Height)
117			}
118			return p, nil
119		case tea.KeyMsg:
120			if msg.Type == tea.KeyCtrlC ||
121				(msg.Type == tea.KeyRunes && string(msg.Runes) == "q" && p.state != StateAskModule) {
122				return p, tea.Quit
123			}
124		}
125		switch p.state {
126		case StateAskModule:
127			return p.updateAskModule(msg)
128		case StateAskVersionA:
129			return p.updateAskVersionA(msg)
130		case StateAskVersionB:
131			return p.updateAskVersionB(msg)
132		case StateLoading:
133			return p.updateLoading(msg)
134		case StateBrowser:
135			if p.browser == nil {
136				return p, tea.Quit
137			}
138			m, cmd := p.browser.Update(msg)
139			p.browser = m.(*Browser)
140			return p, cmd
141		}
142		return p, nil
143	}
144	
145	func (p *Picker) updateAskModule(msg tea.Msg) (tea.Model, tea.Cmd) {
146		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
147			id, err := parseModuleAddressForPicker(p.input.Value())
148			if err != nil {
149				p.errMessage = err.Error()
150				return p, nil
151			}
152			p.errMessage = ""
153			p.moduleID = id
154			if p.deps == nil || p.deps.Client == nil {
155				// Test harness path: do not dispatch network cmd.
156				return p, nil
157			}
158			p.state = StateLoading
159			return p, p.loadVersionsCmd(id)
160		}
161		var cmd tea.Cmd
162		p.input, cmd = p.input.Update(msg)
163		return p, cmd
164	}
165	
166	func (p *Picker) loadVersionsCmd(id api.ModuleIdentifier) tea.Cmd {
167		return func() tea.Msg {
168			versions, err := p.deps.Client.ListVersions(context.Background(), id)
169			return versionsLoadedMsg{versions: versions, err: err}
170		}
171	}
172	
173	func (p *Picker) updateLoading(msg tea.Msg) (tea.Model, tea.Cmd) {
174		switch m := msg.(type) {
175		case versionsLoadedMsg:
176			if m.err != nil {
177				p.errMessage = m.err.Error()
178				p.state = StateError
179				return p, nil
180			}
181			items := make([]list.Item, 0, len(m.versions))
182			for _, v := range m.versions {
183				items = append(items, versionItem(v))
184			}
185			p.versionsA = list.New(items, list.NewDefaultDelegate(), p.width, p.height-4)
186			p.versionsA.Title = "Select version A"
187			p.state = StateAskVersionA
188			return p, nil
189		case pairLoadedMsg:
190			if m.err != nil {
191				p.errMessage = m.err.Error()
192				p.state = StateError
193				return p, nil
194			}
195			p.pairA = m.a
196			p.pairB = m.b
197			// Stay in StateLoading until SetBrowser is called by the cmd
198			// integration. To make the bubbletea program quit (so the cmd
199			// code can run the second-stage Run), return tea.Quit here. The
200			// cmd integration will inspect Bytes() and either run the
201			// browser or report an error.
202			return p, tea.Quit
203		}
204		var cmd tea.Cmd
205		p.spinner, cmd = p.spinner.Update(msg)
206		return p, cmd
207	}
208	
209	func (p *Picker) updateAskVersionA(msg tea.Msg) (tea.Model, tea.Cmd) {
210		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
211			item, ok := p.versionsA.SelectedItem().(versionItem)
212			if !ok {
213				return p, nil
214			}
215			p.chosenA = string(item)
216			items := make([]list.Item, 0, len(p.versionsA.Items()))
217			for _, it := range p.versionsA.Items() {
218				if v := it.(versionItem); string(v) != p.chosenA {
219					items = append(items, v)
220				}
221			}
222			p.versionsB = list.New(items, list.NewDefaultDelegate(), p.width, p.height-4)
223			p.versionsB.Title = "Select version B"
224			p.state = StateAskVersionB
225			return p, nil
226		}
227		var cmd tea.Cmd
228		p.versionsA, cmd = p.versionsA.Update(msg)
229		return p, cmd
230	}
231	
232	func (p *Picker) updateAskVersionB(msg tea.Msg) (tea.Model, tea.Cmd) {
233		if km, ok := msg.(tea.KeyMsg); ok && km.Type == tea.KeyEnter {
234			item, ok := p.versionsB.SelectedItem().(versionItem)
235			if !ok {
236				return p, nil
237			}
238			p.chosenB = string(item)
239			if p.deps == nil || p.deps.Reg == nil {
240				return p, nil
241			}
242			p.state = StateLoading
243			return p, p.loadPairCmd(p.moduleID, p.chosenA, p.chosenB)
244		}
245		var cmd tea.Cmd
246		p.versionsB, cmd = p.versionsB.Update(msg)
247		return p, cmd
248	}
249	
250	func (p *Picker) loadPairCmd(id api.ModuleIdentifier, va, vb string) tea.Cmd {
251		return func() tea.Msg {
252			a, b, err := p.deps.Reg.FetchPair(context.Background(),
253				api.Module{ModuleIdentifier: id, Version: va},
254				api.Module{ModuleIdentifier: id, Version: vb})
255			return pairLoadedMsg{a: a, b: b, err: err}
256		}
257	}
258	
259	func (p *Picker) View() string {
260		switch p.state {
261		case StateAskModule:
262			errBlock := ""
263			if p.errMessage != "" {
264				errBlock = "\nerror: " + p.errMessage
265			}
266			return "module address (namespace/name/provider):\n" + p.input.View() + errBlock
267		case StateLoading:
268			return p.spinner.View() + " loading…"
269		case StateAskVersionA:
270			return p.versionsA.View()
271		case StateAskVersionB:
272			return p.versionsB.View()
273		case StateBrowser:
274			if p.browser != nil {
275				return p.browser.View()
276			}
277		case StateError:
278			return "error: " + p.errMessage + "\npress q to quit"
279		}
280		return ""
281	}
