283	// parseModuleAddressForPicker mirrors cmd.parseModuleAddress without
284	// the import cycle. Returns a typed error for inline display in the TUI.
285	func parseModuleAddressForPicker(s string) (api.ModuleIdentifier, error) {
286		parts := strings.Split(s, "/")
287		if len(parts) != 3 {
288			return api.ModuleIdentifier{}, fmt.Errorf("module address must be namespace/name/provider, got %q", s)
289		}
290		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
291		if err := id.Validate(); err != nil {
292			return api.ModuleIdentifier{}, err
293		}
294		return id, nil
295	}
