11	// buildTarGz produces a gzipped tar with the given files in memory.
12	// Used by archive, diff, and registry tests.
13	func buildTarGz(t *testing.T, files map[string]string) []byte {
14		t.Helper()
15		var buf bytes.Buffer
16		gz := gzip.NewWriter(&buf)
17		tw := tar.NewWriter(gz)
18		for name, body := range files {
19			hdr := &tar.Header{
20				Name: name,
21				Mode: 0o644,
22				Size: int64(len(body)),
23			}
24			if err := tw.WriteHeader(hdr); err != nil {
25				t.Fatalf("WriteHeader %s: %v", name, err)
26			}
27			if _, err := tw.Write([]byte(body)); err != nil {
28				t.Fatalf("Write %s: %v", name, err)
29			}
30		}
31		if err := tw.Close(); err != nil {
32			t.Fatal(err)
33		}
34		if err := gz.Close(); err != nil {
35			t.Fatal(err)
36		}
37		return buf.Bytes()
38	}
