119	func TestExtractIgnoresSymlinks(t *testing.T) {
120		// Build a tar with a symlink entry plus a regular file. Symlinks
121		// should be silently dropped, the regular file should land in
122		// the output.
123		var buf bytes.Buffer
124		gz := gzip.NewWriter(&buf)
125		tw := tar.NewWriter(gz)
126		for _, hdr := range []*tar.Header{
127			{Name: "link.tf", Typeflag: tar.TypeSymlink, Linkname: "main.tf", Mode: 0o644},
128			{Name: "main.tf", Typeflag: tar.TypeReg, Size: 1, Mode: 0o644},
129		} {
130			if err := tw.WriteHeader(hdr); err != nil {
131				t.Fatal(err)
132			}
133			if hdr.Typeflag == tar.TypeReg {
134				if _, err := tw.Write([]byte("x")); err != nil {
135					t.Fatal(err)
136				}
137			}
138		}
139		if err := tw.Close(); err != nil {
140			t.Fatal(err)
141		}
142		if err := gz.Close(); err != nil {
143			t.Fatal(err)
144		}
145	
146		mod, err := Extract(buf.Bytes(), 1<<20)
147		if err != nil {
148			t.Fatalf("Extract: %v", err)
149		}
150		if _, ok := mod.Files["link.tf"]; ok {
151			t.Error("symlink should have been dropped")
152		}
153		if _, ok := mod.Files["main.tf"]; !ok {
154			t.Error("regular file should be present")
155		}
156	}
